{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "In healthy male subjects, BMS-187745 given as a 50 mg oral solution had a mean absolute bioavailability of 2.6% versus IV, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Agomelatine's absolute oral bioavailability in humans is reported as <5% at the therapeutic oral dose, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Bambuterol oral bioavailability is about 10% in healthy adults compared with intravenous dosing, below the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved quantitative absolute bioavailability records are below 20% (2.6%, <5%, 10%, <10%, <1.7%), and qualitative records consistently indicate poor or low oral bioavailability; therefore the query is predicted to have low oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "The only record spanning the threshold (C11, 5–40%) is a range describing variability, not a definitive absolute F value, so it does not provide affirmative evidence for F >= 20%.",
    "Some supporting records are qualitative ('poor', 'extremely low') rather than numeric absolute F measurements.",
    "Molecule 2's <1.7% estimate is derived from a single patient with assumed maximum clearance, adding uncertainty but not changing direction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

